import{_ as n,o as a,c as i,ai as e}from"./chunks/framework.BxxKhjs3.js";const E=JSON.parse('{"title":"37-while-let 表达式","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/37-while-let 表达式/37-while-let 表达式.md","filePath":"仓颉入门到实战/37-while-let 表达式/37-while-let 表达式.md","lastUpdated":1736065340000,"__rawMarkdown":"# 37-while-let 表达式\\n\\n`while-let` 表达式首先对条件中 `<-` 右侧的表达式进行求值，如果此值能匹配 `<-` 左侧的模式，则执行循环体，然后重复执行此过程。如果模式匹配失败，则结束循环，继续执行 `while-let` 表达式之后的代码。例如：\\n\\n```javascript\\nimport std.random.*\\n\\n// 此函数模拟在通信中接收数据，获取数据可能失败\\nfunc recv(): Option<UInt8> {\\n    let number = Random().nextUInt8()\\n    if (number < 128) {\\n        return Some(number)\\n    }\\n    return None\\n}\\n\\nmain() {\\n    // 模拟循环接收通信数据，如果失败就结束循环\\n    while (let Some(data) <- recv()) {\\n        println(data)\\n    }\\n    println(\\"receive failed\\")\\n}\\n```\\n\\n运行以上程序，可能的输出为：\\n\\n```javascript\\n73\\n94\\nreceive failed\\n```"}'),l={name:"仓颉入门到实战/37-while-let 表达式/37-while-let 表达式.md"};function p(t,s,r,h,c,d){return a(),i("div",null,[...s[0]||(s[0]=[e("",5)])])}const o=n(l,[["render",p]]);export{E as __pageData,o as default};
